const W: World = RAW;

const H = 3_600_000;
const at = (h: number) => new Date(W.NOW + h * H).toISOString();
// Same shapes as server finance lib/approvals (sign, batchChain with no executive threshold).
const sign = (chain: Step[], u: UserRef, when: string): Step[] => {
  const i = chain.findIndex((s) => !s.signedBy);
  return chain.map((s, j) => (j === i ? { ...s, signedBy: { id: u.id, name: u.name }, at: when } : s));
};
const batchChain = (): Step[] => [
  { role: "finance", reason: "preparer" },
  { role: "finance_second", reason: "authoriser", orExec: true },
];
const NOTES = { en: "Thank you for your business.", rw: "Murakoze kutugirira icyizere.", fr: "Merci de votre confiance." };
const TERMS = {
  en: "Valid until the date shown. Government fees are passed through at cost.",
  rw: "Bifite agaciro kugeza ku itariki yerekanwe. Amafaranga ya Leta yishyurwa uko ari.",
  fr: "Valable jusqu'à la date indiquée. Les frais publics sont refacturés au coût réel.",
};

export async function seedFinance(db: Db, o: { encrypt: (plain: string) => string }) {
  const put = async (kind: string, id: string, data: Doc, ref?: string | null) => {
    const status = (data.status ?? data.state ?? null)?.slice(0, 32) ?? null;
    const rev = data.rev ?? 1;
    await db
      .insert(financeRecords)
      .values({ kind, id, status, ref: ref ?? null, data, rev })
      .onConflictDoUpdate({
        target: [financeRecords.kind, financeRecords.id],
        set: { status, ref: ref ?? null, data, rev, updatedAt: sql`now()` },
      });
  };

  // ---- party directory
  for (const c of W.CLIENTS)
    await put("client", c.id, {
      ...c,
      consent: c.id === "cl-nyt" ? { whatsapp: false } : c.id === "cl-rwl" ? { sms: false } : undefined, // F-SET-09 demo consent
    });
  for (const a of W.AGENTS) await put("worker", String(a.id), a);
  for (const s of W.SERVICES) await put("service", s.slug, s);
  for (const c of W.CASES) await put("case", c.ref, c, c.clientId);

  // ---- settings
  for (const s of W.SETTINGS) await put("setting", s.key, s);

  // ---- quotes (+ meta rebuilt from version timestamps)
  type Meta = Doc & { no: string; history: { v: number; status: string; at: string; note?: string }[] };
  const metas = new Map<string, Meta>();
  for (const q of W.QUOTES) {
    await put("quote", `${q.no}#${q.version}`, q, q.no);
    const kind = W.CLIENTS.find((c) => c.id === q.clientId)?.type === "company" ? "company" : "individual";
    const m: Meta = metas.get(q.no) ?? { no: q.no, kind, notes: { ...NOTES }, terms: { ...TERMS }, history: [] };
    if (q.sentAt) m.history.push({ v: q.version, status: "sent", at: q.sentAt });
    if (q.respondedAt)
      m.history.push({
        v: q.version,
        status: q.status === "superseded" ? "changes_requested" : q.status,
        at: q.respondedAt,
        note: q.responseNote,
      });
    if (q.status === "expired") m.history.push({ v: q.version, status: "expired", at: q.validUntil });
    metas.set(q.no, m);
  }
  for (const m of metas.values()) {
    m.history.sort((a, b) => a.at.localeCompare(b.at));
    await put("quote_meta", m.no, m);
  }

  // ---- invoices, client credit, payments
  for (const [n, i] of W.INVOICES.entries()) {
    const id = i.no ?? `DRAFT-seed-${n}`;
    await put("invoice", id, { ...i, id, lang: "en", reminders: [], statement: [] }, i.no);
  }
  const firstPartial = W.INVOICES.find((i) => i.status === "partially_paid");
  if (firstPartial) await put("client_credit", firstPartial.clientId, { id: firstPartial.clientId, amount: 12_000 });
  for (const p of W.PAYMENTS) await put("payment", p.id, p, p.invoiceNo);
  for (const p of W.HISTORY) await put("payment", p.id, { ...p, sample: true }, p.invoiceNo);

  // ---- reconciliation
  for (const imp of W.IMPORTS) await put("import", imp.id, { ...imp, at: at(-8), fileName: `${imp.provider}-ledger.csv` }, imp.provider);
  const allPays = [...W.PAYMENTS, ...W.HISTORY];
  for (const l of W.LINES) {
    const p = l.paymentId ? allPays.find((x) => x.id === l.paymentId) : undefined;
    const diff = l.match === "exception" && p ? l.amount - (p.amountReceived ?? p.amountExpected) : undefined;
    await put("line", l.id, { ...l, rev: 1, diff }, l.importId);
  }
  for (const k of W.LOCKS) await put("period_lock", `${k.provider}:${k.day}`, k, k.provider);
  await put("mapping", "mtn_momo", {
    id: "mtn_momo",
    mapping: { external_ref: "Reference", amount: "Amount", fee: "Fee", occurred_at: "Date" },
  });

  // ---- refunds, credit notes, receivable notes
  for (const r of W.REFUNDS) await put("refund", r.no, r, r.invoiceNo);
  for (const cn of W.CREDIT_NOTES) await put("credit_note", cn.no, cn, cn.invoiceNo);
  await put(
    "ar_note",
    "n-seed-kff",
    {
      id: "n-seed-kff",
      clientId: "cl-kff",
      at: at(-50),
      by: W.USERS.finance2.name,
      text: "Accounts promised payment after their month-end run.",
      promiseAt: at(24 * 6).slice(0, 10),
    },
    "cl-kff",
  );

  // ---- revenue: rules (chain = proposer finance + approver), allocations, adjustments, fees
  for (const r of W.RULES) {
    let chain = sign(
      r.agentPct === 3000
        ? [{ role: "finance", reason: "proposer" }]
        : [
            { role: "finance", reason: "proposer" },
            { role: "executive", reason: "deviation" },
          ],
      W.USERS.finance,
      `${r.from}T08:00:00.000Z`,
    );
    if (r.approvedBy) chain = sign(chain, r.approvedBy, `${r.from}T09:00:00.000Z`);
    await put("rule", r.id, { ...r, chain });
  }
  for (const a of W.ALLOCATIONS) await put("allocation", a.id, { ...a, rev: 1 }, a.caseRef);
  for (const a of W.ADJUSTMENTS) {
    const chain = a.refundNo
      ? []
      : sign(
          [
            { role: "finance", reason: "proposer" },
            { role: "finance_second", reason: "secondSigner", orExec: true },
          ],
          W.USERS.finance,
          at(-5),
        );
    await put("adjustment", a.id, { ...a, chain, createdBy: W.USERS.finance, at: at(-5) }, a.workerId);
  }
  for (const x of W.FEES) await put("fee", x.id, x, x.workerId);

  // ---- payouts: batches with signed chains and line parts, destinations (one unverified, one cooling — D-14)
  for (const b of W.BATCHES) {
    const meta = Object.fromEntries(
      b.lines.map((l) => [
        l.id,
        {
          parts: {
            allocations: W.ALLOCATIONS.filter((a) => a.batchNo === b.no && a.shares.some((s) => s.workerId === l.workerId)).map((a) => ({
              id: a.id,
              caseRef: a.caseRef,
              amount: a.shares.find((s) => s.workerId === l.workerId)?.amount ?? 0,
            })),
            adjustments: [],
            fees: [],
          },
          carriedIn: 0,
          taxable: l.gross + l.adjustments,
          carriedFrom: [],
          paidAt: `${b.period}-05T09:00:00.000Z`,
        },
      ]),
    );
    const chain = sign(
      sign(batchChain(), b.preparedBy, `${b.period}-03T09:00:00.000Z`),
      b.authorisedBy ?? W.USERS.finance2,
      `${b.period}-04T09:00:00.000Z`,
    );
    await put("batch", b.no, { ...b, chain, rev: 1, meta }, b.period);
  }
  const DEST = [
    ["ag-eric", "mtn_momo", "•••• 0214", true],
    ["ag-grace", "airtel_money", "•••• 7731", true],
    ["ag-jp", "bank", "BK •••• 4410", true],
    ["ag-patrick", "bank", "EQ •••• 9902", true],
    ["ag-claudine", "mtn_momo", "•••• 5528", false],
    ["ag-david", "airtel_money", "•••• 3307", true],
  ] as const;
  for (const [id, method, masked, verified] of DEST)
    await put("destination", id, {
      id,
      method,
      masked,
      verified,
      ...(id === "ag-david" && { coolingUntil: new Date(Date.now() + 30 * H).toISOString() }),
    });

  // ---- payout accounts (numbers encrypted at rest; same shape as finance.core newAccount)
  const U = W.USERS;
  const ACC = [
    ["acc-1", "Operating account", "bank", "000140110214", U.finance, U.finance2],
    ["acc-2", "MTN MoMo merchant", "mtn_momo", "250788100321", U.finance, U.finance2],
    ["acc-3", "Airtel Money merchant", "airtel_money", "250730200487", U.finance2, U.finance],
    ["acc-4", "Disbursement account", "bank", "000140117790", U.finance2, U.finance],
  ] as const;
  for (const [id, name, method, number, addedBy, verifiedBy] of ACC)
    await put("account", id, {
      id,
      name,
      method,
      status: "verified",
      addedBy,
      verifiedBy,
      numberEnc: o.encrypt(number),
      last4: number.slice(-4),
    });

  // ---- sequences: continue after the highest seeded number per series and year
  const nos = [
    ...W.INVOICES.map((i) => i.no),
    ...W.QUOTES.map((q) => q.no),
    ...W.PAYMENTS.map((p) => p.receiptNo),
    ...W.HISTORY.map((p) => p.receiptNo),
    ...W.CREDIT_NOTES.map((c) => c.no),
    ...W.REFUNDS.map((r) => r.no),
  ];
  const last = new Map<string, number>();
  for (const no of nos) {
    const m = no?.match(/^([A-Z]+-\d{4})-(\d+)$/);
    if (m) last.set(m[1], Math.max(last.get(m[1]) ?? 0, Number(m[2])));
  }
  for (const [key, n] of last) await db.insert(financeSequences).values({ key, last: n }).onConflictDoNothing();
}
